import Cocoa
final class DirectoryTreeNode {
 let path:String;let name:String;let link:Bool;var children:[DirectoryTreeNode]?;var loading=false;var expandRequested=false;var error:String?
 init(path:String,name:String,link:Bool=false){self.path=path;self.name=name;self.link=link}
}
final class DirectoryTreeView:NSView,NSOutlineViewDataSource,NSOutlineViewDelegate {
 typealias Loader=(String,@escaping(Result<[DirectoryTreeNode],Error>)->Void)->Void
