 let bar=NSStackView();for(title,action) in [("根目录",#selector(goRoot)),("当前",#selector(goCurrent)),("刷新",#selector(refresh))]{let b=NSButton(title:title,target:self,action:action);b.isBordered=false;b.font = .systemFont(ofSize:10);bar.addArrangedSubview(b)};stack.addArrangedSubview(bar);let column=NSTableColumn(identifier:.init("directory"));column.title="目录树";column.width=180;outline.addTableColumn(column);outline.outlineTableColumn=column;outline.delegate=self;outline.dataSource=self;outline.registerForDraggedTypes([scpPasteboard,.fileURL]);outline.rowHeight=23;outline.indentationPerLevel=13;outline.headerView=nil;outline.target=self;outline.doubleAction = #selector(openSelected);let scroll=NSScrollView();scroll.hasVerticalScroller=true;scroll.hasHorizontalScroller=true;scroll.documentView=outline;scroll.borderType = .bezelBorder;stack.addArrangedSubview(scroll);scroll.widthAnchor.constraint(equalTo:stack.widthAnchor).isActive=true;scroll.heightAnchor.constraint(greaterThanOrEqualToConstant:100).isActive=true;status.font = .systemFont(ofSize:10);status.lineBreakMode = .byTruncatingMiddle;stack.addArrangedSubview(status);status.widthAnchor.constraint(equalTo:stack.widthAnchor).isActive=true
